static struct tpci200_board * check_slot ( struct ipack_device * dev ) { struct tpci200_board * tpci200 ; tpci200 = dev_get_drvdata ( dev -> bus -> parent ) ; if ( tpci200 == NULL ) { dev_info ( & dev -> dev , "carrier board not found\n" ) ; return NULL ; } if ( dev -> slot >= TPCI200_NB_SLOT ) { dev_info ( & dev -> dev , "Slot [%d:%d] doesn't exist! Last tpci200 slot is %d.\n" , dev -> bus -> bus_nr , dev -> slot , TPCI200_NB_SLOT - 1 ) ; return NULL ; } return tpci200 ; } 